{
  "name": "rf_cal_drain_ring",
  "confidence": "medium",
  "docstring": "Advances a 64-entry RF calibration ring by a requested count, clears pending entries encountered during the scan, updates the ring index and 12-bit counter, and dispatches the context handler.",
  "subsystem": "rf",
  "var_renames": {
    "result": "ctx",
    "a2": "count",
    "v2": "i",
    "v3": "head_idx",
    "v4": "valid_cnt",
    "v5": "ring_idx",
    "v6": "entry_addr",
    "v7": "new_head_idx",
    "v8": "seq_cnt"
  },
  "struct_hints": [
    {
      "offset": 8,
      "meaning": "uint16 12-bit sequence/consumed counter"
    },
    {
      "offset": 10,
      "meaning": "uint8 ring head index modulo 64"
    },
    {
      "offset": 11,
      "meaning": "uint8 pending/valid entry count"
    },
    {
      "offset": 16,
      "meaning": "uint32 ring entry array base, stride 4"
    }
  ]
}
